'use strict';

/**
* BLAS level 2 routine to solve one of the systems of equations `A*x = b` or `A^T*x = b` where `b` and `x` are `N` element ndarrays and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular matrix.
*
* @module @stdlib/blas/base/ndarray/dtrsv
*
* @example
* var Float64Vector = require( '@stdlib/ndarray/vector/float64' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
* var Float64Array = require( '@stdlib/array/float64' );
* var dtrsv = require( '@stdlib/blas/base/ndarray/dtrsv' );
*
* var x = new Float64Vector( [ 1.0, 2.0, 3.0 ] );
* var A = new ndarray( 'float64', new Float64Array( [ 1.0, 2.0, 3.0, 0.0, 4.0, 5.0, 0.0, 0.0, 6.0 ] ), [ 3, 3 ], [ 3, 1 ], 0, 'row-major' );
*
* var out = dtrsv( [ x, A ] );
* // returns <ndarray>[ -0.25, -0.125, 0.5 ]
*
* var bool = ( out === x );
* // returns true
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
